  1 | import fs from "node:fs";
  2 | import path from "node:path";
  3 | import express from "express";
  4 | import type { NextFunction, Request, Response } from "express";
  5 | import { isSlug, listAssignments, loadAssignment } from "./assignments";
  6 | import { nextHint, startSession } from "./agent";
  7 | import { HEARTBEAT_MS } from "./config";
  8 | import { sanitizeTestResults } from "./eventFilter";
  9 | import { runAssignment } from "./runner";
 10 | import {
 11 |   addClient,
 12 |   createSession,
 13 |   emitEvent,
 14 |   getSession,
 15 |   removeClient,
 16 |   setStatus,
 17 | } from "./sessions";
 18 | import { openSse, writeSseComment } from "./sse";
 19 | import type { Assignment } from "./types";
