 21 | export function createApp(): express.Express {
 22 |   const app = express();
 23 |   app.use(express.json({ limit: "1mb" }));
 24 | 
 25 |   app.get("/api/health", (_req, res) => {
 26 |     res.json({ status: "ok" });
 27 |   });
 28 | 
 29 |   app.get("/api/assignments", (_req, res) => {
 30 |     const assignments = listAssignments();
 31 |     res.json(
 32 |       assignments.map((a) => ({
 33 |         id: a.id,
 34 |         language: a.language,
 35 |         statement: a.statement,
 36 |         starterCode: a.starterCode,
 37 |       })),
 38 |     );
 39 |   });
 40 | 
 41 |   app.post("/api/session", async (req: Request, res: Response, next: NextFunction) => {
 42 |     try {
 43 |       const body: unknown = req.body;
 44 |       if (typeof body !== "object" || body === null || Array.isArray(body)) {
 45 |         res.status(400).json({ error: "request body must be a JSON object" });
 46 |         return;
 47 |       }
 48 | 
 49 |       const assignmentId = (body as Record<string, unknown>).assignmentId;
 50 |       if (!isSlug(assignmentId)) {
 51 |         res.status(400).json({ error: "assignmentId is required and must be a plain slug" });
 52 |         return;
 53 |       }
 54 | 
 55 |       let assignment: Assignment;
 56 |       try {
 57 |         assignment = loadAssignment(assignmentId);
 58 |       } catch {
 59 |         res.status(404).json({ error: `unknown assignment: ${assignmentId}` });
 60 |         return;
 61 |       }
 62 | 
 63 |       const codeRaw = (body as Record<string, unknown>).code;
 64 |       let code: string;
 65 |       if (codeRaw === undefined || codeRaw === null || codeRaw === "") {
 66 |         code = assignment.starterCode;
 67 |       } else if (typeof codeRaw !== "string") {
 68 |         res.status(400).json({ error: "code must be a string" });
 69 |         return;
 70 |       } else {
 71 |         code = codeRaw;
 72 |       }
 73 | 
 74 |       // Run the runner WITHOUT cleanup so the temp workdir persists for the
 75 |       // agent. The workdir is the agent's sandbox and lives until the session
 76 |       // ends/TTL, at which point the session cleanup loop removes it.
 77 |       const testResults = await runAssignment(assignment, code, { cleanup: false });
 78 | 
 79 |       const session = createSession({
 80 |         assignmentId: assignment.id,
 81 |         language: assignment.language,
 82 |         statement: assignment.statement,
 83 |         workdir: testResults.sandboxDir,
 84 |         testResults,
 85 |       });
 86 | 
 87 |       // Record the test results first so they replay before any agent event.
 88 |       emitEvent(session, "test_results", testResults);
 89 |       setStatus(session, "running");
 90 | 
 91 |       // Fire-and-forget: ask the agent for a level-1 hint in the background.
 92 |       startSession(session.id).catch((err) => {
 93 |         emitEvent(session, "error", { message: err instanceof Error ? err.message : String(err) });
 94 |         setStatus(session, "error");
 95 |       });
 96 | 
 97 |       res.json({ sessionId: session.id, testResults: sanitizeTestResults(testResults) });
 98 |     } catch (err) {
 99 |       next(err);
100 |     }
101 |   });
102 | 
103 |   app.get("/api/session/:id/stream", (req: Request, res: Response) => {
104 |     const session = getSession(String(req.params.id));
105 |     if (!session) {
106 |       res.status(404).json({ error: "unknown session" });
107 |       return;
108 |     }
109 | 
110 |     openSse(res);
111 |     res.write(": connected\n\n");
112 |     addClient(session, res); // replays buffered events + registers for live events
113 | 
114 |     const heartbeat = setInterval(() => {
115 |       try {
116 |         writeSseComment(res, "ping");
117 |       } catch {
118 |         /* ignore */
119 |       }
120 |     }, HEARTBEAT_MS);
121 |     heartbeat.unref();
122 | 
123 |     res.on("close", () => {
124 |       clearInterval(heartbeat);
125 |       removeClient(session, res);
126 |     });
127 |   });
128 | 
129 |   app.post("/api/session/:id/next-hint", async (req: Request, res: Response, next: NextFunction) => {
130 |     try {
131 |       const session = getSession(String(req.params.id));
132 |       if (!session) {
133 |         res.status(404).json({ error: "unknown session" });
134 |         return;
135 |       }
136 |       if (session.busy) {
137 |         res.status(409).json({ error: "agent is still busy", status: session.status });
138 |         return;
139 |       }
140 |       const result = await nextHint(session.id);
141 |       res.json(result);
142 |     } catch (err) {
143 |       const status = (err as { status?: number }).status;
144 |       if (status === 404) {
145 |         res.status(404).json({ error: "unknown session" });
146 |         return;
147 |       }
148 |       if (status === 409) {
149 |         res.status(409).json({ error: "agent is still busy" });
150 |         return;
151 |       }
152 |       next(err);
153 |     }
154 |   });
155 | 
156 |   const webDir = path.resolve(process.cwd(), "web");
157 |   if (fs.existsSync(webDir)) {
158 |     app.use(express.static(webDir));
159 |   }
160 | 
161 |   // eslint-disable-next-line @typescript-eslint/no-explicit-any
162 |   app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
163 |     const status = typeof err?.status === "number" ? err.status : 500;
164 |     if (status >= 400 && status < 500) {
165 |       res.status(status).json({ error: "invalid request body" });
166 |       return;
167 |     }
168 |     console.error(err);
169 |     res.status(500).json({ error: "internal server error" });
170 |   });
171 | 
172 |   return app;
173 | }

