 42 | const GIVE_HINT_DESCRIPTION = [
 43 |   "Show the student exactly one hint at the requested level.",
 44 |   "level 1 = a conceptual nudge; level 2 = point to the area or line of the bug;",
 45 |   "level 3 = a near-explicit explanation of the bug and the underlying concept.",
