 50 | /**
 51 |  * The shared give_hint tool. It is the only hint sink: the server-side guard runs
 52 |  * here before a hint is recorded, and a rejected hint becomes a tool error so the
 53 |  * model rephrases instead of the hint reaching the student.
 54 |  */
 55 | const giveHintTool = createTool({
 56 |   name: "give_hint",
 57 |   description: GIVE_HINT_DESCRIPTION,
 58 |   inputSchema: z.object({
 59 |     level: z.number().int().min(1).max(3),
 60 |     tag: z.string().optional(),
 61 |     text: z.string(),
 62 |   }),
 63 |   async execute(input, context) {
 64 |     const session = context.sessionId ? getSession(context.sessionId) : undefined;
 65 |     const wanted = session?.currentHintLevel ?? input.level;
 66 | 
 67 |     if (session && input.level !== wanted) {
 68 |       emitEvent(session, "hint_rejected", {
 69 |         level: input.level,
 70 |         wantedLevel: wanted,
 71 |         reason: "wrong level",
 72 |       });
 73 |       throw new Error(
 74 |         `You were asked for a level ${wanted} hint, but called give_hint with level ${input.level}. ` +
 75 |           `Call give_hint again with level ${wanted}.`,
 76 |       );
 77 |     }
 78 | 
 79 |     if (session && session.hints.some((h) => h.level === input.level)) {
 80 |       // This level was already delivered; tell the model to stop without erroring,
 81 |       // so it finishes its turn instead of retrying forever.
 82 |       return {
 83 |         shown: false,
 84 |         alreadyDelivered: true,
 85 |         message: `The level ${input.level} hint was already delivered. Do not call give_hint again; finish your turn.`,
 86 |       };
 87 |     }
 88 | 
 89 |     const guard = checkHint(input.text);
 90 |     if (!guard.ok) {
 91 |       if (session) {
 92 |         // Never surface the rejected text — only a fixed reason category.
 93 |         emitEvent(session, "hint_rejected", {
 94 |           level: input.level,
 95 |           reason: categorizeHintReason(guard.reason),
 96 |         });
 97 |       }
 98 |       throw new Error(
 99 |         `HintLab rejected this hint: ${guard.reason}. Rephrase the hint in plain prose with no code, ` +
100 |           `then call give_hint again.`,
101 |       );
102 |     }
103 | 
104 |     const hint = {
105 |       level: input.level as 1 | 2 | 3,
106 |       tag: input.tag,
107 |       text: input.text,
108 |       at: new Date().toISOString(),
109 |     };
110 |     if (session) {
111 |       recordHint(session, hint);
112 |     }
113 |     return { shown: true, level: input.level };
114 |   },
115 | });
