124 | /**
125 |  * The hardened test runner exposed to the agent. It replaces the SDK's built-in
126 |  * run_commands (which is disabled) so that student code run by the agent goes
127 |  * through the server's own runner — process-group kill, timeouts, and a minimal
128 |  * env with HOME set to the sandbox dir. Student code therefore can never read
129 |  * the server's environment or the credentials in ~/.cline.
130 |  */
131 | const runTestsTool = createTool({
132 |   name: "run_tests",
133 |   description: RUN_TESTS_DESCRIPTION,
134 |   inputSchema: z.object({ testName: z.string().optional() }),
135 |   async execute(input, context) {
136 |     const session = context.sessionId ? getSession(context.sessionId) : undefined;
137 |     if (!session) {
138 |       return { error: "no active session" };
139 |     }
140 |     const assignment = loadAssignment(session.assignmentId);
141 |     return runTestsInWorkdir(assignment, session.workdir, input.testName);
142 |   },
