162 | function capabilities() {
163 |   return {
164 |     // Every tool that is not explicitly auto-approved is denied. run_commands is
165 |     // disabled at the policy level (and would be denied here as defence-in-depth),
166 |     // so a command attempt is still blocked and shown as an approval-denied line.
167 |     requestToolApproval: async (req: {
168 |       sessionId: string;
169 |       toolName: string;
170 |       toolCallId: string;
171 |       input: unknown;
172 |     }) => {
173 |       const session = getSession(req.sessionId);
174 |       const commands = extractCommands(req.input);
175 |       const reason =
176 |         req.toolName === "run_commands"
177 |           ? "Command blocked by allow-list"
178 |           : `Tool "${req.toolName}" is not allowed in HintLab`;
179 | 
180 |       if (session) {
181 |         emitEvent(session, "approval", {
182 |           toolName: req.toolName,
183 |           toolCallId: req.toolCallId,
184 |           commands,
185 |           allowed: false,
186 |           reason,
187 |         });
188 |       }
189 |       return { approved: false, reason };
190 |     },
191 |   };
