194 | /** Map the raw SDK events to HintLab SSE events, routed by session id. */
195 | function handleCoreEvent(e: {
196 |   type: string;
197 |   payload?: { sessionId?: string; event?: Record<string, unknown>; [k: string]: unknown };
198 | }): void {
199 |   const sessionId = e.payload?.sessionId;
200 |   if (!sessionId) return;
201 |   const session = getSession(sessionId);
202 |   if (!session) return;
203 | 
204 |   if (e.type === "agent_event") {
205 |     const ev = e.payload?.event as Record<string, unknown> | undefined;
206 |     if (!ev) return;
207 |     switch (ev.type) {
208 |       case "content_start":
209 |         // Only tool starts are forwarded (and then filtered to the allow-list).
210 |         // Model text and reasoning are dropped here and never emitted.
211 |         if (ev.contentType === "tool") {
212 |           emitEvent(session, "tool_call", { toolName: ev.toolName, toolCallId: ev.toolCallId, input: ev.input });
213 |         }
214 |         break;
215 |       case "content_end":
216 |         if (ev.contentType === "tool") {
217 |           emitEvent(session, "tool_result", {
218 |             toolName: ev.toolName,
219 |             toolCallId: ev.toolCallId,
220 |             output: ev.output,
221 |             error: ev.error,
222 |             durationMs: ev.durationMs,
223 |           });
224 |         }
225 |         break;
226 |       case "done":
227 |         emitEvent(session, "done", { reason: ev.reason });
228 |         break;
229 |       case "error":
230 |         emitEvent(session, "error", {
231 |           message: ev.error instanceof Error ? ev.error.message : String(ev.error),
232 |         });
233 |         break;
234 |       default:
235 |         break;
236 |     }
237 |     return;
238 |   }
239 | 
240 |   if (e.type === "status") {
241 |     emitEvent(session, "status", { status: e.payload?.status });
242 |   } else if (e.type === "ended") {
243 |     emitEvent(session, "done", { reason: e.payload?.reason });
244 |   } else if (e.type === "hook") {
245 |     const payload = e.payload as Record<string, unknown>;
246 |     emitEvent(session, "status", { hook: payload.hookEventName, toolName: payload.toolName });
247 |   }
248 | }
