263 | // Register the hook so session cleanup can stop the SDK session too.
264 | setStopAgentHook((agentSessionId) => {
265 |   if (!clineCorePromise) return;
266 |   clineCorePromise
267 |     .then((cline) => cline.stop(agentSessionId).catch(() => undefined))
268 |     .catch(() => undefined);
269 | });
