326 | /** Run the first (level-1) agent turn in the background for a session. */
327 | export async function startSession(sessionId: string): Promise<void> {
328 |   const session = getSession(sessionId);
329 |   if (!session) return;
330 | 
331 |   const mainFile = session.language === "python" ? "main.py" : "main.c";
332 |   const mainPath = path.resolve(session.workdir, mainFile);
333 |   const testsPath = path.resolve(session.workdir, "tests.json");
334 | 
335 |   const cline = await getCline();
336 |   session.busy = true;
337 |   setStatus(session, "running");
338 | 
339 |   try {
340 |     const startPromise = cline.start({
341 |       interactive: true,
342 |       prompt: buildFirstPrompt(session, mainPath, testsPath),
343 |       config: {
344 |         sessionId: session.id,
345 |         providerId: HINTLAB_PROVIDER_ID,
346 |         modelId: HINTLAB_MODEL_ID,
347 |         temperature: 0,
348 |         systemPrompt: SYSTEM_PROMPT,
349 |         // session.workdir is the runner's temp sandbox dir, kept alive for the
350 |         // agent via runAssignment(..., { cleanup: false }) in app.ts. It is the
351 |         // agent's whole sandbox and is removed by the session cleanup loop when
352 |         // the session ends/TTL expires (see sessions.ts deleteSession).
353 |         cwd: session.workdir,
354 |         workspaceRoot: session.workdir,
355 |         enableTools: true,
356 |         enableSpawnAgent: false,
357 |         enableAgentTeams: false,
358 |         extraTools: [giveHintTool as unknown as AgentTool, runTestsTool as unknown as AgentTool],
359 |       },
360 |       toolPolicies: toolPolicies(),
361 |       capabilities: capabilities(),
362 |     });
363 |     startPromise.catch(() => undefined); // swallow late settle after a timeout
364 | 
365 |     const result = await withTimeout(startPromise, AGENT_TURN_TIMEOUT_MS, "Tutor timed out, try again");
366 | 
367 |     session.agentSessionId = result.sessionId;
368 |     registerAgentSession(result.sessionId, session.id);
369 |     const finishReason = (result.result as { finishReason?: string } | undefined)?.finishReason;
370 |     emitEvent(session, "status", { message: "initial agent turn finished", finishReason });
371 |   } catch (err) {
372 |     emitEvent(session, "error", { message: err instanceof Error ? err.message : String(err) });
373 |     setStatus(session, "error");
374 |   } finally {
375 |     session.busy = false;
376 |     if (session.status !== "error") {
377 |       setStatus(session, session.hints.length >= 3 ? "complete" : "idle");
378 |     }
379 |   }
380 | }
381 | 
382 | /** Ask the agent for the next hint level (2, then 3). Returns after the turn completes. */
383 | export async function nextHint(sessionId: string): Promise<{ level: number; status: string; message?: string }> {
384 |   const session = getSession(sessionId);
385 |   if (!session) throw Object.assign(new Error("unknown session"), { status: 404 });
386 |   if (session.busy) throw Object.assign(new Error("agent is still busy"), { status: 409 });
387 |   if (session.hints.length >= 3) {
388 |     return { level: 3, status: "complete", message: "All three hint levels have already been delivered." };
389 |   }
390 | 
391 |   const nextLevel = Math.min(session.hints.length + 1, 3);
392 |   session.currentHintLevel = nextLevel;
393 |   session.busy = true;
394 |   setStatus(session, "running");
395 | 
396 |   const cline = await getCline();
397 |   try {
398 |     const sendPromise = cline.send({
399 |       sessionId: session.agentSessionId ?? session.id,
400 |       prompt: buildNextPrompt(session, nextLevel),
401 |     });
402 |     sendPromise.catch(() => undefined); // swallow late settle after a timeout
403 |     const result = await withTimeout(sendPromise, AGENT_TURN_TIMEOUT_MS, "Tutor timed out, try again");
404 |     const finishReason = (result as { finishReason?: string } | undefined)?.finishReason;
405 |     emitEvent(session, "status", { message: `level ${nextLevel} agent turn finished`, finishReason });
406 |   } catch (err) {
407 |     emitEvent(session, "error", { message: err instanceof Error ? err.message : String(err) });
408 |     setStatus(session, "error");
409 |   } finally {
410 |     session.busy = false;
411 |     if (session.status !== "error") {
412 |       setStatus(session, session.hints.length >= 3 ? "complete" : "idle");
413 |     }
414 |   }
415 | 
416 |   return { level: nextLevel, status: session.status };
417 | }
418 | 
419 | // Export the tool so tests can inspect it if needed.
420 | export { giveHintTool };
421 |

