 20 | function validateAssignment(id: string, raw: unknown): Assignment {
 21 |   if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
 22 |     throw new Error(`assignment ${id}: tests.json must be a JSON object`);
 23 |   }
 24 |   const obj = raw as Record<string, unknown>;
 25 | 
 26 |   const assignmentId = obj.assignmentId;
 27 |   if (typeof assignmentId !== "string" || assignmentId.length === 0) {
 28 |     throw new Error(`assignment ${id}: "assignmentId" must be a non-empty string`);
 29 |   }
 30 | 
 31 |   const language = obj.language;
 32 |   if (language !== "python" && language !== "c") {
 33 |     throw new Error(`assignment ${id}: "language" must be "python" or "c"`);
 34 |   }
 35 | 
 36 |   const statement = obj.statement;
 37 |   if (typeof statement !== "string" || statement.length === 0) {
 38 |     throw new Error(`assignment ${id}: "statement" must be a non-empty string`);
 39 |   }
 40 | 
 41 |   const run = obj.run;
 42 |   if (typeof run !== "string" || run.trim().length === 0) {
 43 |     throw new Error(`assignment ${id}: "run" must be a non-empty string`);
 44 |   }
 45 | 
 46 |   let build: string | undefined;
 47 |   if (obj.build !== undefined) {
 48 |     if (typeof obj.build !== "string" || obj.build.trim().length === 0) {
 49 |       throw new Error(`assignment ${id}: "build" must be a non-empty string when present`);
 50 |     }
 51 |     build = obj.build;
 52 |   }
 53 | 
 54 |   const tests = obj.tests;
 55 |   if (!Array.isArray(tests) || tests.length === 0) {
 56 |     throw new Error(`assignment ${id}: "tests" must be a non-empty array`);
 57 |   }
 58 | 
 59 |   const parsedTests: TestCase[] = tests.map((t, i) => {
 60 |     if (typeof t !== "object" || t === null || Array.isArray(t)) {
 61 |       throw new Error(`assignment ${id}: tests[${i}] must be an object`);
 62 |     }
 63 |     const tc = t as Record<string, unknown>;
 64 |     if (typeof tc.name !== "string" || tc.name.length === 0) {
 65 |       throw new Error(`assignment ${id}: tests[${i}].name must be a non-empty string`);
 66 |     }
 67 |     if (typeof tc.input !== "string") {
 68 |       throw new Error(`assignment ${id}: tests[${i}].input must be a string`);
 69 |     }
 70 |     if (typeof tc.expected !== "string") {
 71 |       throw new Error(`assignment ${id}: tests[${i}].expected must be a string`);
 72 |     }
 73 |     return { name: tc.name, input: tc.input, expected: tc.expected };
 74 |   });
 75 | 
 76 |   return {
 77 |     id,
 78 |     assignmentId,
 79 |     language: language as Language,
 80 |     statement,
 81 |     build,
 82 |     run,
 83 |     tests: parsedTests,
 84 |     starterCode: "",
 85 |   };
