 88 | export function loadAssignment(id: string): Assignment {
 89 |   if (!isSlug(id)) {
 90 |     throw new Error(`invalid assignment id: ${JSON.stringify(id)}`);
 91 |   }
 92 | 
 93 |   const dir = path.join(ASSIGNMENTS_DIR, id);
 94 |   const testsJsonPath = path.join(dir, "tests.json");
 95 |   if (!fs.existsSync(testsJsonPath)) {
 96 |     throw new Error(`unknown assignment: ${id}`);
 97 |   }
 98 | 
 99 |   let raw: unknown;
100 |   try {
101 |     raw = JSON.parse(fs.readFileSync(testsJsonPath, "utf8"));
102 |   } catch (err) {
103 |     throw new Error(`assignment ${id}: failed to parse tests.json: ${(err as Error).message}`);
104 |   }
105 | 
106 |   const assignment = validateAssignment(id, raw);
107 | 
108 |   const starterFile = assignment.language === "python" ? "main.py" : "main.c";
109 |   const starterPath = path.join(dir, starterFile);
110 |   if (!fs.existsSync(starterPath)) {
111 |     throw new Error(`assignment ${id}: missing starter file ${starterFile}`);
112 |   }
113 |   assignment.starterCode = fs.readFileSync(starterPath, "utf8");
114 | 
115 |   return assignment;
116 | }
117 | 
118 | export function listAssignments(): Assignment[] {
119 |   if (!fs.existsSync(ASSIGNMENTS_DIR)) return [];
120 | 
121 |   const entries = fs.readdirSync(ASSIGNMENTS_DIR, { withFileTypes: true });
122 |   const ids = entries
123 |     .filter(
124 |       (e) =>
125 |         e.isDirectory() &&
126 |         isSlug(e.name) &&
127 |         fs.existsSync(path.join(ASSIGNMENTS_DIR, e.name, "tests.json")),
128 |     )
129 |     .map((e) => e.name)
130 |     .sort();
131 | 
132 |   return ids.map((id) => loadAssignment(id));
133 | }

  1 | /**
  2 |  * HintLab run_commands allow-list.
  3 |  *
  4 |  * `run_commands` executes on the HOST (inside the session workdir), so this
  5 |  * allow-list is the only thing standing between the model and an arbitrary
  6 |  * shell. It is deliberately strict and exported so scripts/check-agent.ts can
  7 |  * unit-test it.
  8 |  */
  9 | 
 10 | export interface AllowDecision {
 11 |   allowed: boolean;
 12 |   reason?: string;
 13 | }
 14 | 
 15 | /**
 16 |  * Substrings that are rejected on every command before the whitelist match runs.
 17 |  * This is defence-in-depth: even a command that happens to satisfy a structural
 18 |  * regex (for example the free-form payload of an `echo ... | python3 main.py`)
 19 |  * is still rejected if it smuggles shell metacharacters.
 20 |  */
 21 | export const DENY_SUBSTRINGS: readonly string[] = [
 22 |   ";", // command separator
 23 |   "&&", // and-list
 24 |   "||", // or-list
 25 |   "`", // command substitution
 26 |   "$", // any dollar sign: variable or command expansion ($HOME, $(…), ${…})
 27 |   "|", // any pipe — echo/printf piping into the program is disallowed entirely
 28 |   ">", // output redirection (writing files)
 29 |   "&", // backgrounding / single ampersand
 30 |   "\n", // literal newline = another command
 31 |   "\r", // literal carriage return
 32 |   "*", // glob expansion
 33 |   "?", // glob expansion
 34 | ];
 35 | 
 36 | /**
 37 |  * The whitelist. Each trimmed command must match exactly one of these anchored
 38 |  * patterns. Only the assignment's own build/run/read commands are allowed.
 39 |  */
 40 | export const ALLOWED_COMMANDS: readonly RegExp[] = [
 41 |   // --- Python: run the program ---
 42 |   /^python3 main\.py$/,
 43 |   // stdin redirect from a per-test input file in the workdir (no slashes)
 44 |   /^python3 main\.py < input-[A-Za-z0-9_-]+\.txt$/,
 45 |   // --- C: build + run ---
 46 |   /^gcc -Wall -O0 main\.c -o main$/, // the exact tests.json build command
 47 |   /^\.\/main$/,
 48 |   /^\.\/main < input-[A-Za-z0-9_-]+\.txt$/,
 49 |   // --- Reads ---
 50 |   /^cat (main\.py|main\.c|tests\.json|input-[A-Za-z0-9_-]+\.txt)$/,
 51 | ];
 52 | 
 53 | /**
 54 |  * Normalise the (loosely-typed) run_commands input into a flat list of command
 55 |  * strings. Handles both the simple `{ commands: string[] }` shape and the
 56 |  * structured `{ command, args }` / string forms the SDK accepts.
 57 |  */
 58 | export function extractCommands(input: unknown): string[] {
 59 |   if (input == null) return [];
 60 |   const obj = input as Record<string, unknown>;
 61 |   const raw: unknown = "commands" in obj ? obj.commands : input;
 62 | 
 63 |   if (Array.isArray(raw)) {
 64 |     return raw
 65 |       .map((c): string | undefined => {
 66 |         if (typeof c === "string") return c;
 67 |         if (c && typeof c === "object") return (c as Record<string, unknown>).command as string | undefined;
 68 |         return undefined;
 69 |       })
 70 |       .filter((c): c is string => typeof c === "string" && c.trim().length > 0);
 71 |   }
 72 | 
 73 |   if (typeof raw === "string") return [raw];
 74 |   if (raw && typeof raw === "object") {
 75 |     const c = (raw as Record<string, unknown>).command;
 76 |     if (typeof c === "string") return [c];
 77 |   }
 78 |   return [];
 79 | }
 80 | 
 81 | /** Decide whether a single (trimmed) command is allowed. */
 82 | export function allowCommand(command: string): AllowDecision {
 83 |   const cmd = command.trim();
 84 |   if (!cmd) return { allowed: false, reason: "empty command" };
 85 | 
 86 |   for (const sub of DENY_SUBSTRINGS) {
 87 |     if (cmd.includes(sub)) {
 88 |       return { allowed: false, reason: `forbidden token ${JSON.stringify(sub)}` };
 89 |     }
 90 |   }
 91 | 
 92 |   if (!ALLOWED_COMMANDS.some((re) => re.test(cmd))) {
 93 |     return { allowed: false, reason: "command not on the HintLab allow-list" };
 94 |   }
 95 | 
 96 |   return { allowed: true };
 97 | }
 98 | 
 99 | /** Decide whether a list of commands is allowed (every command must be allowed). */
100 | export function allowCommands(commands: string[]): AllowDecision {
101 |   if (commands.length === 0) return { allowed: false, reason: "no commands provided" };
102 |   for (const c of commands) {
103 |     const d = allowCommand(c);
104 |     if (!d.allowed) return d;
105 |   }
106 |   return { allowed: true };
107 | }

 1 | /**
 2 |  * HintLab hint guard.
 3 |  *
 4 |  * Before a hint is stored or sent to the student, it is checked here. If it
 5 |  * contains a fenced code block, inline code that is more than a short
 6 |  * identifier/expression, multiple source-code-like lines, or anything that looks
 7 |  * like a rewritten solution, it is rejected (and give_hint returns an error so
 8 |  * the model rephrases without code).
 9 |  */
10 | 
11 | export interface HintCheck {
12 |   ok: boolean;
13 |   reason?: string;
14 | }
15 | 
16 | /** Builtins whose `name(` form is a strong signal of a code expression. */
17 | const CODE_FUNCTION_RE =
18 |   /\b(?:range|len|sum|print|printf|scanf|input|append|split|map|list|int|float|str|lower|replace|strip|reversed|enumerate|zip|sorted|min|max|open|read|write|fgets|gets|puts)\s*\(/;
19 | 
20 | /** A single line that looks like actual source code / a rewritten solution. */
21 | const CODE_LINE_PATTERNS: readonly RegExp[] = [
22 |   /^\s*(def|class|import|from|return|print|printf|scanf|#include|else|elif)\b/,
23 |   /^\s*(for|while|if)\s*\(/, // C control structures
24 |   /^\s*(for|while|if|elif|else)\b[^:]*:$/, // Python control structures ending in ":"
25 |   CODE_FUNCTION_RE,
26 |   /[A-Za-z_]\w*\s*(?:=|\+=|-=|\*=|\/=|%=)\s*[^=]/, // assignment
27 |   /\b(?:int|float|double|char|void|long|short|unsigned)\s+\w+\s*[=;(\[]/, // C declaration
28 |   /(?:\(float\)|\(int\)|\(double\)|\(char\))/, // C casts (e.g. (float) sum / n)
29 |   /;\s*$/, // trailing semicolon (C statement)
30 |   /->/, // C struct/member dereference
31 |   // --- identifiers combined with real code syntax ---
32 |   /[\w)\]]\s*\[[^\]\n]*\]/, // indexing / slicing: nums[i], s[::-1], s.lower()[::-1]
33 |   /\w\s*(?:==|!=|<=|>=)\s*\w/, // comparison operators between identifiers
34 |   /\w\s+[+\-*/%<>]\s+\w/, // spaced arithmetic/comparison (so "and/or" and
35 |   // hyphenated words like "off-by-one" are not flagged)
36 | ];
37 | 
38 | function looksLikeCodeLine(line: string): boolean {
39 |   const s = line.trim();
40 |   if (!s) return false;
41 |   return CODE_LINE_PATTERNS.some((re) => re.test(s));
42 | }
43 | 
44 | /** Fixed categories used when a hint rejection is surfaced to a client. */
45 | export type HintRejectCategory = "wrong level" | "contained code" | "empty hint";
46 | 
47 | /** Map any guard reason to a small, fixed category (never reveals hint text). */
48 | export function categorizeHintReason(reason?: string): HintRejectCategory {
49 |   if (reason === "wrong level") return "wrong level";
50 |   if (reason === "empty hint") return "empty hint";
51 |   return "contained code";
52 | }
53 | 
54 | /**
55 |  * Check a hint's text. Returns `{ ok: true }` when it is safe to show, otherwise
56 |  * `{ ok: false, reason }` describing what made it look like code.
57 |  */
58 | export function checkHint(text: string): HintCheck {
59 |   const t = text.trim();
60 |   if (!t) return { ok: false, reason: "empty hint" };
61 | 
62 |   // 1. Fenced code blocks.
63 |   if (t.includes("```")) {
64 |     return { ok: false, reason: "contains a fenced code block" };
65 |   }
66 | 
67 |   // 2. Inline code spans: allow only a short identifier/expression.
68 |   const inline = t.matchAll(/`([^`\n]+)`/g);
69 |   for (const m of inline) {
70 |     const code = m[1].trim();
71 |     if (code.length > 20) {
72 |       return { ok: false, reason: "inline code is longer than a short identifier/expression" };
73 |     }
74 |     // Reject inline code that is clearly an expression rather than a plain name.
75 |     if (/[(){}\[\]=<>;:,]|->/.test(code)) {
76 |       return { ok: false, reason: "inline code looks like an expression" };
77 |     }
78 |   }
79 | 
80 |   // 3. Any line that looks like source code / a rewritten solution.
81 |   const lines = t.split("\n");
82 |   if (lines.some(looksLikeCodeLine)) {
83 |     return { ok: false, reason: "text looks like source code or a rewritten solution" };
84 |   }
85 | 
86 |   return { ok: true };
87 | }

 80 |       // This level was already delivered; tell the model to stop without erroring,
 81 |       // so it finishes its turn instead of retrying forever.
 82 |       return {
 83 |         shown: false,
 84 |         alreadyDelivered: true,
 85 |         message: `The level ${input.level} hint was already delivered. Do not call give_hint again; finish your turn.`,
 86 |       };
 87 |     }
 88 | 
 89 |     const guard = checkHint(input.text);
 90 |     if (!guard.ok) {
 91 |       if (session) {
 92 |         // Never surface the rejected text — only a fixed reason category.
 93 |         emitEvent(session, "hint_rejected", {
 94 |           level: input.level,
 95 |           reason: categorizeHintReason(guard.reason),
 96 |         });
 97 |       }
 98 |       throw new Error(
 99 |         `HintLab rejected this hint: ${guard.reason}. Rephrase the hint in plain prose with no code, ` +
100 |           `then call give_hint again.`,
101 |       );
102 |     }
103 | 
104 |     const hint = {
105 |       level: input.level as 1 | 2 | 3,
106 |       tag: input.tag,
107 |       text: input.text,
108 |       at: new Date().toISOString(),
109 |     };
110 |     if (session) {
111 |       recordHint(session, hint);
112 |     }
113 |     return { shown: true, level: input.level };
114 |   },
115 | });
