312 | /** Resolve/reject a promise within `ms`, with a friendly timeout message. */
313 | async function withTimeout<T>(p: Promise<T>, ms: number, label: string): Promise<T> {
314 |   let timer: NodeJS.Timeout | undefined;
315 |   const timeout = new Promise<never>((_, reject) => {
316 |     timer = setTimeout(() => reject(new Error(label)), ms);
317 |     timer.unref?.();
318 |   });
319 |   try {
320 |     return await Promise.race([p, timeout]);
321 |   } finally {
322 |     if (timer) clearTimeout(timer);
323 |   }
324 | }
