 68 | function minimalEnv(home: string): NodeJS.ProcessEnv {
 69 |   const pathEnv = process.env.PATH ?? "/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin";
 70 |   return {
 71 |     PATH: pathEnv,
 72 |     HOME: home,
