 77 | /** Human-readable description for common fatal signals (used in stderr). */
 78 | const SIGNAL_DESCRIPTIONS: Record<string, string> = {
 79 |   SIGSEGV: "segmentation fault",
 80 |   SIGABRT: "aborted",
 81 |   SIGFPE: "floating point exception",
 82 |   SIGILL: "illegal instruction",
 83 |   SIGBUS: "bus error",
 84 |   SIGTRAP: "trace/breakpoint trap",
 85 |   SIGSYS: "bad system call",
 86 | };
