 93 | function killProcessTree(child: ChildProcess): void {
 94 |   if (child.pid === undefined) return;
 95 |   try {
 96 |     // detached:true makes the child its own process-group leader on POSIX,
 97 |     // so killing the group reaps any grandchildren too.
 98 |     if (process.platform !== "win32") {
 99 |       process.kill(-child.pid, "SIGKILL");
100 |     } else {
101 |       child.kill("SIGKILL");
102 |     }
103 |   } catch {
104 |     try {
105 |       child.kill("SIGKILL");
106 |     } catch {
107 |       /* already gone */
108 |     }
109 |   }
110 | }
