239 |   if (assignment.build) {
240 |     const b = await spawnCommand(assignment.build, {
241 |       cwd: workdir,
242 |       timeoutMs: BUILD_TIMEOUT_MS,
243 |       maxOutputBytes: MAX_OUTPUT_BYTES,
244 |     });
245 |     build = {
246 |       ok: !b.timedOut && b.exitCode === 0,
247 |       stdout: b.stdout,
248 |       stderr: b.stderr,
249 |       timedOut: b.timedOut,
250 |       signal: b.signal,
251 |     };
252 |     if (!build.ok) {
253 |       return { build, tests: [], passed: 0, failed: 0, total: 0 };
254 |     }
255 |   }
256 | 
257 |   const slug = testName ? slugifyTestName(testName) : undefined;
258 |   const toRun = slug ? assignment.tests.filter((t) => slugifyTestName(t.name) === slug) : assignment.tests;
259 | 
260 |   const tests: TestResult[] = [];
261 |   for (const test of toRun) {
262 |     const r = await spawnCommand(assignment.run, {
263 |       cwd: workdir,
264 |       input: test.input,
265 |       timeoutMs: RUN_TIMEOUT_MS,
266 |       maxOutputBytes: MAX_OUTPUT_BYTES,
267 |     });
268 |     const got = r.stdout.trim();
269 |     const passed = !r.timedOut && r.exitCode === 0 && got === test.expected;
270 |     tests.push({
