112 | function spawnCommand(command: string, config: SpawnConfig): Promise<SpawnOutcome> {
113 |   const tokens = tokenize(command);
114 |   if (tokens.length === 0) {
115 |     return Promise.resolve({ stdout: "", stderr: "empty command", exitCode: null, signal: null, timedOut: false });
116 |   }
117 | 
118 |   const [cmd, ...args] = tokens;
119 | 
120 |   return new Promise((resolve) => {
121 |     let stdout = "";
122 |     let stderr = "";
123 |     let exitCode: number | null = null;
124 |     let signal: string | null = null;
125 |     let timedOut = false;
126 |     let settled = false;
127 | 
128 |     const child = spawn(cmd, args, {
129 |       cwd: config.cwd,
130 |       env: minimalEnv(config.cwd),
131 |       stdio: ["pipe", "pipe", "pipe"],
132 |       detached: process.platform !== "win32",
133 |     });
134 | 
135 |     const append = (target: "stdout" | "stderr", chunk: Buffer) => {
136 |       const text = chunk.toString("utf8");
137 |       if (target === "stdout") {
138 |         const space = config.maxOutputBytes - stdout.length;
139 |         if (space > 0) stdout += text.slice(0, space);
140 |       } else {
141 |         const space = config.maxOutputBytes - stderr.length;
142 |         if (space > 0) stderr += text.slice(0, space);
143 |       }
144 |     };
145 | 
146 |     // Kill the whole process group exactly once, no matter how the run ends
147 |     // (normal exit, spawn error, timeout, ...). detached:true made the child its
148 |     // own group leader on POSIX, so this also reaps any grandchildren it forked
149 |     // (e.g. a `subprocess.Popen(['sleep','31'])` that would otherwise survive).
150 |     let killed = false;
151 |     const killGroup = () => {
152 |       if (killed) return;
153 |       killed = true;
154 |       killProcessTree(child);
155 |     };
156 | 
157 |     const finish = () => {
158 |       if (settled) return;
159 |       settled = true;
160 |       clearTimeout(timer);
161 |       killGroup();
162 |       resolve({ stdout, stderr, exitCode, signal, timedOut });
163 |     };
164 | 
165 |     const timer = setTimeout(() => {
166 |       timedOut = true;
167 |       finish();
168 |     }, config.timeoutMs);
169 | 
170 |     child.stdout?.on("data", (d: Buffer) => append("stdout", d));
171 |     child.stderr?.on("data", (d: Buffer) => append("stderr", d));
172 | 
173 |     child.once("error", (err) => {
174 |       stderr += `\n[runner] failed to spawn '${cmd}': ${err.message}`;
175 |       finish();
176 |     });
177 | 
178 |     child.once("exit", (code, sig) => {
179 |       exitCode = code;
180 |       // Our own timeout SIGKILL is not a crash: it is already reported via
181 |       // `timedOut`, so only record a signal when the program died on its own.
182 |       if (sig && !timedOut) {
183 |         signal = sig;
184 |         stderr += `\n[runner] Program terminated by signal ${sig}${describeSignal(sig)}\n`;
185 |       }
186 |       finish();
187 |     });
188 | 
189 |     child.stdin?.on("error", () => {
190 |       /* ignore EPIPE if the process exited before reading stdin */
191 |     });
192 | 
193 |     if (config.input !== undefined) {
194 |       child.stdin?.write(config.input);
195 |     }
196 |     child.stdin?.end();
197 |   });
198 | }
