128 | // Independent code markers (beyond the guard) used to re-verify hints contain no code.
129 | function hasCodeMarker(text: string): boolean {
130 |   if (text.includes("```")) return true;
131 |   return /(?:\bdef\s+\w+\s*\(|\bprint\s*\(|\bprintf\s*\(|\bscanf\s*\(|\brange\s*\(|\blen\s*\(|\bsum\s*\(|\bwhile\s*\(|\bif\s*\(|\(float\)|\(int\)|;\s*$|\w\s*\[[^\]\n]*\]|\w\s*(?:==|!=|<=|>=)\s*\w|\w\s+[+\-*/%<>]\s+\w)/.test(
132 |     text,
133 |   );
134 | }
