199 |           eventTypes.add(name);
200 |           if (name === "hint") hints.push(data as { level: number; tag?: string; text: string });
201 |           else if (name === "approval") approvals.push(data as { toolName?: string; commands?: string[]; allowed?: boolean; reason?: string });
202 |           else if (name === "tool_call") toolCalls.push(data as { toolName?: string });
203 |           else if (name === "status" && data && typeof (data as { status?: unknown }).status === "string") {
204 |             lastStatus = (data as { status: string }).status;
205 |           }
206 |         }
207 |       }
208 |     } catch {
