 48 | async function readSse(sessionId: string): Promise<{ eventTypes: Set<string>; hint: unknown }> {
 49 |   const eventTypes = new Set<string>();
 50 |   let hint: unknown = null;
 51 | 
 52 |   const controller = new AbortController();
 53 |   const timeout = setTimeout(() => controller.abort(), HINT_TIMEOUT_MS);
 54 | 
 55 |   try {
 56 |     const res = await fetch(`${BASE}/api/session/${sessionId}/stream`, { signal: controller.signal });
 57 |     if (!res.body) throw new Error("no response body");
 58 |     const reader = res.body.getReader();
 59 |     const decoder = new TextDecoder();
 60 |     let buffer = "";
 61 |     for (;;) {
 62 |       const { done, value } = await reader.read();
 63 |       if (done) break;
 64 |       buffer += decoder.decode(value, { stream: true });
 65 |       let idx: number;
 66 |       while ((idx = buffer.indexOf("\n\n")) >= 0) {
 67 |         const block = buffer.slice(0, idx);
 68 |         buffer = buffer.slice(idx + 2);
 69 |         let name = "message";
 70 |         const dataLines: string[] = [];
 71 |         for (const line of block.split("\n")) {
 72 |           if (line.startsWith(":")) continue;
 73 |           if (line.startsWith("event:")) name = line.slice(6).trim();
 74 |           else if (line.startsWith("data:")) dataLines.push(line.slice(5).trimStart());
 75 |         }
 76 |         if (dataLines.length === 0) continue;
 77 |         eventTypes.add(name);
 78 |         let data: unknown;
 79 |         try {
 80 |           data = JSON.parse(dataLines.join("\n"));
 81 |         } catch {
 82 |           data = dataLines.join("\n");
 83 |         }
 84 |         if (name === "hint") {
 85 |           if (hint === null) hint = data;
 86 |           return { eventTypes, hint };
 87 |         }
 88 |       }
 89 |     }
 90 |   } catch {
 91 |     /* aborted on timeout or closed — fine */
 92 |   } finally {
 93 |     clearTimeout(timeout);
 94 |   }
 95 |   return { eventTypes, hint };
 96 | }
