 98 | function killTree(child: ChildProcess): void {
 99 |   if (child.pid === undefined) return;
100 |   try {
101 |     if (process.platform !== "win32") {
102 |       process.kill(-child.pid, "SIGKILL");
103 |     } else {
104 |       child.kill("SIGKILL");
105 |     }
106 |   } catch {
107 |     try {
108 |       child.kill("SIGKILL");
109 |     } catch {
110 |       /* already gone */
111 |     }
112 |   }
113 | }
